SELECT productId, prodName, brand, c.categoryId, inboundPrice, price, heelHeight, discRate, minGrade, status, TO_CHAR(regDate, 'YYYY-MM-DD') regDate , c.ctgName , thumbnail FROM product p LEFT OUTER JOIN category c ON p.categoryId = c.categoryId
AND regDate >= TO_DATE(#{dateFrom}, 'YYYY-MM-DD')
AND regDate < TO_DATE(#{dateTo}, 'YYYY-MM-DD') + 1
AND minGrade >= #{minGrade}
AND status = #{status}
ORDER BY productId DESC OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY

SELECT COUNT(*) FROM product p LEFT OUTER JOIN category c ON p.categoryId = c.categoryId
AND regDate >= TO_DATE(#{dateFrom}, 'YYYY-MM-DD')
AND regDate < TO_DATE(#{dateTo}, 'YYYY-MM-DD') + 1
AND minGrade >= #{minGrade}
AND status = #{status}

SELECT productId, prodName, price, thumbnail
FROM product
WHERE productId = #{productId}
